// Pins the Gradle daemon to JDK 17 on every `expo prebuild` (roadmap P0.x
// hygiene, not a product feature).
//
// Why a plugin and not a note in the README: `android/` is generated by
// Continuous Native Generation, so anything written there by hand is gone on
// the next prebuild - and the failure it prevents costs an hour every time.
//
// Why the daemon criteria file and not just `org.gradle.java.home`: Gradle
// documents that the criteria (`gradle/gradle-daemon-jvm.properties`) "takes
// precedence over JAVA_HOME and org.gradle.java.home". Android Studio writes
// that file when it picks a "Gradle JDK", and its bundled JBR is newer than
// 21 (25 today). On JDK 24+ JEP 472 turns `System.load` into a restricted
// method, Android Gradle Plugin aborts its native tasks, and the user only
// sees `WARNING: A restricted method in java.lang.System has been called` -
// which reads as a CMake bug and is not one. So the plugin seeds the criteria
// at 17 (the version this app builds with) and keeps `org.gradle.java.home`
// in step as a belt for tooling that ignores the criteria.
//
// When a JDK 17 cannot be found, the plugin writes nothing at all: the build
// then behaves exactly as it did before (JAVA_HOME wins), which is what CI
// wants - it installs the JDK it needs and sets `CI` besides.
//
// Escape hatch: `SETUNO_GRADLE_JDK=C:\path\to\jdk-17` overrides detection.

const fs = require("node:fs")
const os = require("node:os")
const path = require("node:path")
const {
  withDangerousMod,
  withGradleProperties,
  withProjectBuildGradle,
} = require("expo/config-plugins")

const REQUIRED_MAJOR = 17
const DAEMON_CRITERIA = "gradle/gradle-daemon-jvm.properties"
const JAVA_HOME_PROPERTY = "org.gradle.java.home"
const INSTALLATIONS_PROPERTY = "org.gradle.java.installations.paths"
const GUARD_MARKER = "setunoJdkMajor"

/** The major version a JDK home declares, or null when it is not a JDK. */
function majorVersion(home) {
  try {
    const release = fs.readFileSync(path.join(home, "release"), "utf8")
    const match = /^JAVA_VERSION="(\d+)/m.exec(release)
    return match ? Number(match[1]) : null
  } catch {
    return null
  }
}

/** A JDK home, following the macOS bundle layout when it is one. */
function asJdkHome(candidate) {
  if (majorVersion(candidate) !== null) return candidate
  const nested = path.join(candidate, "Contents", "Home")
  return majorVersion(nested) !== null ? nested : null
}

/** Directories that hold JDK installations on the platforms this app ships from. */
function jdkDirectories() {
  const home = os.homedir()
  return [
    path.join(home, ".jdks"),
    path.join(home, ".sdkman", "candidates", "java"),
    "/Library/Java/JavaVirtualMachines",
    "/usr/lib/jvm",
    "C:\\Program Files\\Java",
    "C:\\Program Files\\Eclipse Adoptium",
    "C:\\Program Files\\Microsoft",
    "C:\\Program Files\\Amazon Corretto",
  ]
}

/** Every plausible JDK home, most explicit first. */
function candidates() {
  const explicit = [process.env.SETUNO_GRADLE_JDK, process.env.JAVA_HOME].filter(
    Boolean,
  )
  const discovered = []
  for (const directory of jdkDirectories()) {
    let entries = []
    try {
      entries = fs.readdirSync(directory)
    } catch {
      continue
    }
    for (const entry of entries) {
      discovered.push(path.join(directory, entry))
    }
  }
  return [...explicit, ...discovered]
}

/** The first JDK 17 on this machine, or null. */
function findJdk17() {
  for (const candidate of candidates()) {
    const home = asJdkHome(candidate)
    if (home && majorVersion(home) === REQUIRED_MAJOR) return home
  }
  return null
}

/** Gradle reads a properties value, so a Windows path needs forward slashes. */
function gradlePath(home) {
  return home.replace(/\\/g, "/")
}

/**
 * Seeds the daemon JVM criteria with 17.
 *
 * The file is rewritten on every prebuild on purpose: it is the one Android
 * Studio may have left at 25, and a stale one is exactly the bug this plugin
 * exists to prevent.
 */
function withDaemonCriteria(config, jdkHome) {
  return withDangerousMod(config, [
    "android",
    async (withMods) => {
      const root = withMods.modRequest.platformProjectRoot
      if (!root) return withMods
      const file = path.join(root, DAEMON_CRITERIA)
      fs.mkdirSync(path.dirname(file), { recursive: true })
      fs.writeFileSync(
        file,
        [
          "# Generated by plugins/withGradleJdk17.js during `expo prebuild`.",
          "#",
          "# Gradle's daemon JVM criteria take precedence over JAVA_HOME and",
          "# org.gradle.java.home, so this file - not the IDE dropdown - is what",
          "# decides which JDK runs the Android build. Android Gradle Plugin's",
          "# native tasks abort on JDK 24+ (JEP 472's restricted System.load), so",
          "# this app builds on 17. Android Studio rewrites the file when you pick",
          "# another \"Gradle JDK\"; keep that setting at 17.",
          "",
          `toolchainVersion=${REQUIRED_MAJOR}`,
          "",
        ].join("\n"),
      )
      return withMods
    },
  ])
}

/** Keeps `org.gradle.java.home` (and the toolchain search path) on the same JDK. */
function withGradleJavaHome(config, jdkHome) {
  return withGradleProperties(config, (withMods) => {
    const wanted = [
      [JAVA_HOME_PROPERTY, gradlePath(jdkHome)],
      [INSTALLATIONS_PROPERTY, gradlePath(jdkHome)],
    ]
    for (const [key, value] of wanted) {
      const existing = withMods.modResults.find(
        (item) => item.type === "property" && item.key === key,
      )
      if (existing) {
        existing.value = value
      } else {
        withMods.modResults.push({ type: "property", key, value })
      }
    }
    return withMods
  })
}

/**
 * Fails the build with a readable message when the daemon still ends up on a
 * JDK that cannot run AGP's native tasks, instead of letting CMake print the
 * restricted-method warning and stop three minutes later.
 */
function withJdkGuard(config) {
  return withProjectBuildGradle(config, (withMods) => {
    if (withMods.modResults.language !== "groovy") return withMods
    if (withMods.modResults.contents.includes(GUARD_MARKER)) return withMods
    withMods.modResults.contents += [
      "",
      "// Setuno: AGP's native tasks abort on JDK 24+ (\"a restricted method in",
      "// java.lang.System has been called\"), so the Gradle daemon must run on 17.",
      "// `expo prebuild` seeds android/gradle/gradle-daemon-jvm.properties with 17;",
      "// Android Studio overwrites it when its Gradle JDK setting changes.",
      "def setunoJdkMajor = org.gradle.api.JavaVersion.current().majorVersion.toInteger()",
      "if (setunoJdkMajor >= 24) {",
      "    throw new GradleException(",
      "        \"Setuno builds need JDK 17 and Gradle is running on JDK ${setunoJdkMajor}. \" +",
      "        \"Delete android/gradle/gradle-daemon-jvm.properties and set Android Studio's \" +",
      "        \"Gradle JDK to 17, or run `npx expo prebuild --platform android` again.\"",
      "    )",
      "}",
      "",
    ].join("\n")
    return withMods
  })
}

module.exports = function withGradleJdk17(config) {
  // CI installs the JDK it needs and says so through JAVA_HOME; pinning 17
  // there would silently change the toolchain a workflow chose.
  if (process.env.CI) return config

  const jdkHome = findJdk17()
  if (!jdkHome) {
    console.warn(
      "withGradleJdk17: no JDK 17 found, leaving the Gradle JVM unset",
    )
    return config
  }

  let next = config
  next = withGradleJavaHome(next, jdkHome)
  next = withDaemonCriteria(next, jdkHome)
  next = withJdkGuard(next)
  return next
}
